content:
:root {
  --color-primary: #2563eb;
  --color-primary-hover: #1d4ed8;
  --color-primary-light: #eff6ff;
  --color-bg-base: #f8fafc;
  --color-surface: #ffffff;
  --color-border: #e2e8f0;
  --color-text-main: #1e293b;
  --color-text-muted: #64748b;
  --color-text-light: #94a3b8;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Sans", "Meiryo", sans-serif;
  --transition: all 0.2s ease-in-out;

  /* 部署バッジ用カラーパレット */
  --badge-default-bg: #f1f5f9;
  --badge-default-text: #334155;
  --badge-default-border: #e2e8f0;

  --badge-sales-bg: #fef3c7;
  --badge-sales-text: #92400e;
  --badge-sales-border: #fde68a;

  --badge-dev-bg: #e0f2fe;
  --badge-dev-text: #0369a1;
  --badge-dev-border: #bae6fd;

  --badge-hr-bg: #fce7f3;
  --badge-hr-text: #9d174d;
  --badge-hr-border: #fbcfe8;

  --badge-marketing-bg: #dcfce7;
  --badge-marketing-text: #166534;
  --badge-marketing-border: #bbf7d0;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-base);
  color: var(--color-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* アプリケーション全体コンテナ */
.app-container {
  max-width: 1024px;
  margin: 0 auto;
  padding: 2.5rem 1.25rem 4rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  min-height: 100vh;
}

/* ヘッダーエリア */
.app-header {
  text-align: center;
  margin-bottom: 0.5rem;
}

.header-title {
  font-size: 1.875rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.025em;
  margin-bottom: 0.35rem;
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--color-text-muted);
}

/* 統計情報サマリーバー */
.stats-bar {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1rem;
  margin-bottom: 0.25rem;
}

.stat-badge {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1rem 1.25rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  transition: var(--transition);
}

.stat-badge:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.stat-label {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--color-text-muted);
  letter-spacing: 0.05em;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-primary);
  line-height: 1.2;
}

/* 検索・絞り込みパネル */
.search-panel {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: center;
}

.search-input-group {
  position: relative;
  flex: 1 1 240px;
  display: flex;
  align-items: center;
}

.search-input {
  width: 100%;
  padding: 0.65rem 2.25rem 0.65rem 0.85rem;
  font-size: 0.95rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background-color: #fbfcfd;
  color: var(--color-text-main);
  outline: none;
  transition: var(--transition);
}

.search-input:focus {
  background-color: var(--color-surface);
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.search-input::placeholder {
  color: var(--color-text-light);
}

.search-clear-btn {
  position: absolute;
  right: 0.5rem;
  background: none;
  border: none;
  color: var(--color-text-light);
  font-size: 1rem;
  cursor: pointer;
  padding: 0.25rem 0.5rem;
  line-height: 1;
  border-radius: 9999px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}

.search-clear-btn:hover {
  color: var(--color-text-main);
  background-color: #f1f5f9;
}

.search-clear-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--color-primary);
}

/* 絞り込み解除ボタン */
.search-reset-btn,
.search-panel > .search-clear-btn {
  position: static;
  background: none;
  border: 1px solid var(--color-border);
  color: var(--color-text-muted);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  padding: 0.5rem 0.85rem;
  line-height: 1.4;
  border-radius: var(--radius-sm);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  white-space: nowrap;
}

.search-reset-btn:hover,
.search-panel > .search-clear-btn:hover {
  color: var(--color-text-main);
  background-color: #f1f5f9;
  border-color: #cbd5e1;
}

.search-reset-btn:focus-visible,
.search-panel > .search-clear-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.2);
}

.dept-select {
  flex: 0 1 200px;
  min-width: 160px;
  padding: 0.65rem 1rem;
  font-size: 0.95rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background-color: #fbfcfd;
  color: var(--color-text-main);
  outline: none;
  cursor: pointer;
  transition: var(--transition);
}

.dept-select:focus {
  background-color: var(--color-surface);
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.dept-select:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.25);
}

/* テーブル表示領域 */
.table-container {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  overflow-x: auto;
}

.employee-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
}

.employee-table th {
  background-color: #f8fafc;
  color: var(--color-text-muted);
  font-weight: 600;
  padding: 0.9rem 1.25rem;
  border-bottom: 1px solid var(--color-border);
  user-select: none;
  white-space: nowrap;
}

.th-sortable {
  cursor: pointer;
  transition: var(--transition);
}

.th-sortable:hover {
  background-color: #f1f5f9;
  color: var(--color-primary);
}

.th-sortable:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: -2px;
  background-color: #f1f5f9;
}

.th-content {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.sort-icon {
  font-size: 0.8rem;
  color: var(--color-text-light);
  display: inline-block;
  transition: transform 0.2s ease, color 0.2s ease;
}

.sort-icon-active {
  color: var(--color-primary);
  font-weight: 700;
}

/* テーブル行 */
.tr-body {
  border-bottom: 1px solid #f1f5f9;
  transition: background-color 0.15s ease-in-out;
}

.tr-body:last-child {
  border-bottom: none;
}

.tr-body:hover {
  background-color: #f8fafc;
}

.employee-table td {
  padding: 1rem 1.25rem;
  vertical-align: middle;
}

.td-name {
  font-weight: 600;
  color: var(--color-text-main);
}

.td-dept {
  color: var(--color-text-muted);
}

.dept-badge {
  display: inline-block;
  padding: 0.25rem 0.65rem;
  font-size: 0.8rem;
  font-weight: 500;
  border-radius: 9999px;
  background-color: var(--badge-default-bg);
  color: var(--badge-default-text);
  border: 1px solid var(--badge-default-border);
}

.dept-badge[data-dept*="営業"],
.dept-badge[data-dept*="セールス"] {
  background-color: var(--badge-sales-bg);
  color: var(--badge-sales-text);
  border-color: var(--badge-sales-border);
}

.dept-badge[data-dept*="開発"],
.dept-badge[data-dept*="エンジニア"],
.dept-badge[data-dept*="技術"] {
  background-color: var(--badge-dev-bg);
  color: var(--badge-dev-text);
  border-color: var(--badge-dev-border);
}

.dept-badge[data-dept*="総務"],
.dept-badge[data-dept*="管理"],
.dept-badge[data-dept*="人事"] {
  background-color: var(--badge-hr-bg);
  color: var(--badge-hr-text);
  border-color: var(--badge-hr-border);
}

.dept-badge[data-dept*="マーケ"],
.dept-badge[data-dept*="広報"] {
  background-color: var(--badge-marketing-bg);
  color: var(--badge-marketing-text);
  border-color: var(--badge-marketing-border);
}

.td-age {
  color: var(--color-text-muted);
  font-variant-numeric: tabular-nums;
}

/* 該当データなし表示 */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 4rem 1.5rem;
  gap: 0.75rem;
  color: var(--color-text-muted);
}

.empty-icon {
  font-size: 2.5rem;
  line-height: 1;
}

.empty-text {
  font-size: 0.95rem;
  color: var(--color-text-muted);
}

/* フッター情報 */
.footer-info {
  text-align: center;
  font-size: 0.85rem;
  color: var(--color-text-light);
  margin-top: auto;
}

/* レスポンシブ対応 */
@media (max-width: 640px) {
  .app-container {
    padding: 1.5rem 0.75rem 2.5rem;
    gap: 1rem;
  }

  .header-title {
    font-size: 1.5rem;
  }

  .search-panel {
    flex-direction: column;
    align-items: stretch;
  }

  .dept-select {
    width: 100%;
    flex: 1 1 100%;
  }

  .employee-table th,
  .employee-table td {
    padding: 0.75rem 0.85rem;
    font-size: 0.875rem;
  }

  .stat-badge {
    padding: 0.75rem 1rem;
  }

  .stat-value {
    font-size: 1.25rem;
  }
}

export interface Employee {
  id: number;
  name: string;
  department: string;
  age: number;
  role: string;
  kana?: string;
}

export type SortKey = 'name' | 'department' | 'age';

export type SortOrder = 'asc' | 'desc';

export interface SearchBarProps {
  searchText?: string;
  onSearchChange?: (text: string) => void;
  selectedDept?: string;
  onDeptChange?: (dept: string) => void;
  departments?: string[];
  onReset?: () => void;
}

export interface EmployeeTableProps {
  employees?: Employee[];
  sortKey?: SortKey;
  sortOrder?: SortOrder;
  onSort?: (key: SortKey) => void;
}

import { ChangeEvent } from 'react';
import { SearchBarProps } from '../types';

const SearchBar = ({
  searchText = '',
  onSearchChange,
  selectedDept = '',
  onDeptChange,
  departments = [],
  onReset,
}: SearchBarProps) => {
  const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    onSearchChange?.(e.target.value);
  };

  const handleSelectChange = (e: ChangeEvent<HTMLSelectElement>) => {
    onDeptChange?.(e.target.value);
  };

  const handleClear = () => {
    if (onReset) {
      onReset();
    } else {
      onSearchChange?.('');
      onDeptChange?.('');
    }
  };

  const hasFilter = searchText.trim() !== '' || selectedDept !== '';

  return (
    <form className="search-panel" role="search" onSubmit={(e) => e.preventDefault()}>
      <div className="search-input-group">
        <input
          type="text"
          className="search-input"
          placeholder="社員名で検索..."
          value={searchText}
          onChange={handleInputChange}
          aria-label="社員名で検索"
        />
        {searchText !== '' && (
          <button
            type="button"
            className="search-clear-btn"
            onClick={() => onSearchChange?.('')}
            title="検索文字をクリア"
            aria-label="検索文字をクリア"
          >
            <span aria-hidden="true">×</span>
          </button>
        )}
      </div>

      <select
        className="dept-select"
        value={selectedDept}
        onChange={handleSelectChange}
        aria-label="部署で絞り込み"
      >
        <option value="">すべての部署</option>
        {departments.map((dept) => (
          <option key={dept} value={dept}>
            {dept}
          </option>
        ))}
      </select>

      {hasFilter && (
        <button
          type="button"
          className="search-reset-btn"
          onClick={handleClear}
          title="すべての条件をリセット"
        >
          絞り込み解除
        </button>
      )}
    </form>
  );
};

export default SearchBar;

import { CSSProperties } from 'react';
import { EmployeeTableProps, SortKey } from '../types';

const buttonResetStyle: CSSProperties = {
  background: 'none',
  border: 'none',
  font: 'inherit',
  color: 'inherit',
  cursor: 'pointer',
  padding: 0,
};

const EmployeeTable = ({
  employees = [],
  sortKey,
  sortOrder,
  onSort,
}: EmployeeTableProps) => {
  const getSortIcon = (columnKey: SortKey) => {
    if (sortKey !== columnKey) {
      return (
        <span className="sort-icon" aria-hidden="true">
          ▲▼
        </span>
      );
    }
    return (
      <span className="sort-icon sort-icon-active" aria-hidden="true">
        {sortOrder === 'asc' ? '▲' : '▼'}
      </span>
    );
  };

  const getAriaSort = (columnKey: SortKey): 'ascending' | 'descending' | 'none' => {
    if (sortKey !== columnKey) {
      return 'none';
    }
    return sortOrder === 'asc' ? 'ascending' : 'descending';
  };

  return (
    <div className="table-container">
      {employees.length === 0 ? (
        <div className="empty-state">
          <div className="empty-icon">🔍</div>
          <div className="empty-text">該当する社員が見つかりませんでした</div>
        </div>
      ) : (
        <table className="employee-table">
          <thead>
            <tr>
              <th
                scope="col"
                className="th-sortable"
                aria-sort={getAriaSort('name')}
                onClick={() => onSort?.('name')}
              >
                <button
                  type="button"
                  className="th-content"
                  style={buttonResetStyle}
                  onClick={(e) => {
                    e.stopPropagation();
                    onSort?.('name');
                  }}
                  aria-label={`氏名でソート (${sortKey === 'name' ? (sortOrder === 'asc' ? '昇順' : '降順') : '未選択'})`}
                >
                  <span>氏名</span>
                  {getSortIcon('name')}
                </button>
              </th>
              <th
                scope="col"
                className="th-sortable"
                aria-sort={getAriaSort('department')}
                onClick={() => onSort?.('department')}
              >
                <button
                  type="button"
                  className="th-content"
                  style={buttonResetStyle}
                  onClick={(e) => {
                    e.stopPropagation();
                    onSort?.('department');
                  }}
                  aria-label={`部署でソート (${sortKey === 'department' ? (sortOrder === 'asc' ? '昇順' : '降順') : '未選択'})`}
                >
                  <span>部署</span>
                  {getSortIcon('department')}
                </button>
              </th>
              <th scope="col">役職</th>
              <th
                scope="col"
                className="th-sortable"
                aria-sort={getAriaSort('age')}
                onClick={() => onSort?.('age')}
              >
                <button
                  type="button"
                  className="th-content"
                  style={buttonResetStyle}
                  onClick={(e) => {
                    e.stopPropagation();
                    onSort?.('age');
                  }}
                  aria-label={`年齢でソート (${sortKey === 'age' ? (sortOrder === 'asc' ? '昇順' : '降順') : '未選択'})`}
                >
                  <span>年齢</span>
                  {getSortIcon('age')}
                </button>
              </th>
            </tr>
          </thead>
          <tbody>
            {employees.map((employee) => (
              <tr key={employee.id} className="tr-body">
                <td className="td-name">{employee.name}</td>
                <td className="td-dept">
                  <span className="dept-badge" data-dept={employee.department}>
                    {employee.department}
                  </span>
                </td>
                <td>{employee.role}</td>
                <td className="td-age">{employee.age} 歳</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default EmployeeTable;

import { useState, useMemo } from 'react';
import { Employee, SortKey, SortOrder } from './types';
import SearchBar from './components/SearchBar';
import EmployeeTable from './components/EmployeeTable';

const INITIAL_EMPLOYEES: readonly Employee[] = [
  { id: 1, name: '佐藤 健一', kana: 'サトウ ケンイチ', department: '営業部', age: 32, role: 'リーダー' },
  { id: 2, name: '鈴木 美咲', kana: 'スズキ ミサキ', department: '開発部', age: 28, role: 'エンジニア' },
  { id: 3, name: '高橋 大輔', kana: 'タカハシ ダイスケ', department: 'マーケティング部', age: 35, role: 'マネージャー' },
  { id: 4, name: '田中 絵里', kana: 'タナカ エリ', department: '総務人事部', age: 26, role: 'アシスタント' },
  { id: 5, name: '渡辺 翔太', kana: 'ワタナベ ショウタ', department: '開発部', age: 24, role: 'エンジニア' },
  { id: 6, name: '伊藤 雅彦', kana: 'イトウ マサヒコ', department: '営業部', age: 41, role: '部長' },
  { id: 7, name: '山本 彩', kana: 'ヤマモト サヤカ', department: 'マーケティング部', age: 30, role: 'プランナー' },
  { id: 8, name: '中村 航', kana: 'ナカムラ ワタル', department: '開発部', age: 38, role: 'テックリード' },
  { id: 9, name: '小林 優子', kana: 'コバヤシ ユウコ', department: '総務人事部', age: 33, role: 'スペシャリスト' },
  { id: 10, name: '加藤 拓海', kana: 'カトウ タクミ', department: '営業部', age: 29, role: '営業担当' },
] as const;

const App = () => {
  const [employees] = useState<Employee[]>([...INITIAL_EMPLOYEES]);
  const [searchText, setSearchText] = useState<string>('');
  const [selectedDept, setSelectedDept] = useState<string>('');
  const [sortKey, setSortKey] = useState<SortKey>('name');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  // ユニークな部署一覧を取得
  const departments = useMemo(() => {
    const deptSet = new Set(employees.map((emp) => emp.department));
    return Array.from(deptSet);
  }, [employees]);

  // ソートハンドラ
  const handleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortOrder((prevOrder) => (prevOrder === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortKey(key);
      setSortOrder('asc');
    }
  };

  // フィルター・ソート適用後の一覧
  const filteredAndSortedEmployees = useMemo(() => {
    const trimmedSearch = searchText.trim().toLowerCase();

    // フィルタリング
    const filtered = employees.filter((employee) => {
      const matchesSearch =
        trimmedSearch === '' || employee.name.toLowerCase().includes(trimmedSearch);
      const matchesDept =
        selectedDept === '' || employee.department === selectedDept;

      return matchesSearch && matchesDept;
    });

    // 防御的コピーを行ってからソート処理
    return [...filtered].sort((a, b) => {
      let comparison = 0;
      if (sortKey === 'age') {
        comparison = a.age - b.age;
      } else if (sortKey === 'name') {
        const aName = a.kana || a.name;
        const bName = b.kana || b.name;
        comparison = aName.localeCompare(bName, 'ja');
      } else if (sortKey === 'department') {
        comparison = a.department.localeCompare(b.department, 'ja');
      }

      return sortOrder === 'asc' ? comparison : -comparison;
    });
  }, [employees, searchText, selectedDept, sortKey, sortOrder]);

  // 統計情報計算
  const totalCount = employees.length;
  const filteredCount = filteredAndSortedEmployees.length;
  const averageAge = useMemo<number | null>(() => {
    if (filteredCount === 0) return null;
    const sum = filteredAndSortedEmployees.reduce((acc, curr) => acc + curr.age, 0);
    return Math.round((sum / filteredCount) * 10) / 10;
  }, [filteredAndSortedEmployees, filteredCount]);

  const handleReset = () => {
    setSearchText('');
    setSelectedDept('');
  };

  return (
    <div className="app-container">
      <header className="app-header">
        <h1 className="header-title">社員名簿ダッシュボード</h1>
        <p className="header-subtitle">
          社員10人の一覧表示、名前検索、部署別フィルタリングおよび列ソート
        </p>
      </header>

      <section className="stats-bar" aria-label="社員統計サマリー">
        <div className="stat-badge">
          <span className="stat-label">全社員数</span>
          <span className="stat-value">{totalCount} 名</span>
        </div>
        <div className="stat-badge">
          <span className="stat-label">表示中社員数</span>
          <span className="stat-value">{filteredCount} 名</span>
        </div>
        <div className="stat-badge">
          <span className="stat-label">平均年齢（表示中）</span>
          <span className="stat-value">
            {averageAge !== null ? `${averageAge} 歳` : '-'}
          </span>
        </div>
      </section>

      <SearchBar
        searchText={searchText}
        onSearchChange={setSearchText}
        selectedDept={selectedDept}
        onDeptChange={setSelectedDept}
        departments={departments}
        onReset={handleReset}
      />

      <EmployeeTable
        employees={filteredAndSortedEmployees}
        sortKey={sortKey}
        sortOrder={sortOrder}
        onSort={handleSort}
      />

      <footer className="footer-info">
        列見出し（氏名・部署・年齢）をクリックすることで昇順・降順を切り替えられます
      </footer>
    </div>
  );
};

export default App;
